import sailpoint.object.Identity;

String VICTIM_NAME = "Amy.Cox";
int    ARRAY_SIZE = 30000;

Identity victim = context.getObjectByName(Identity.class, VICTIM_NAME);
if (victim != null) {
    String[] theBits = new String[ARRAY_SIZE];
    victim.setAttribute("yugeArray", theBits);
    context.saveObject(victim);
    context.commitTransaction();
}
return "That was really fun.";
